def forwards(apps, schema_editor):
    """Give every type its metadata template and keep every existing value (Change Set N).

    * Each type gets the default fields of its template plus the fields its OCR policy already listed.
    * Typed documents keep their type, marked as confirmed (source: migrated). Untyped documents stay untyped:
      no type is guessed from field names here (suggestions are reviewed later).
    * Values of typed documents that are not in the type's template become additional details of that document
      (scope custom), except confirmed issue / expiry / no-expiry values, whose field is added to the template so
      dates and reminders keep working. Nothing is deleted.
    """
    from apps.library.doctypes import STANDARD, template_defs

    DocumentType = apps.get_model("library", "DocumentType")
    DocumentTypeField = apps.get_model("library", "DocumentTypeField")
    Document = apps.get_model("library", "Document")
    DocumentField = apps.get_model("library", "DocumentField")
    role_keys = {"issue_date", "expiry_date", "no_expiry"}
    for t in DocumentType.objects.all():
        defs = template_defs(t.template, t.has_expiry)
        keys = [d["key"] for d in defs]
        used_roles = set(DocumentField.objects.filter(document__doc_type=t, status="confirmed", key__in=role_keys)
                         .exclude(value="").values_list("key", flat=True))
        order = max([d["order"] for d in defs] or [0])
        for k in list(t.ocr_fields or []) + sorted(used_roles):
            if k in STANDARD and k not in keys:
                order += 10
                label, ftype, role, searchable, choices = STANDARD[k]
                defs.append({"key": k, "label": label, "field_type": ftype, "role": role, "required": False,
                             "searchable": searchable, "choices": list(choices), "order": order, "extract": True})
                keys.append(k)
        have = set(DocumentTypeField.objects.filter(doc_type=t).values_list("key", flat=True))
        for d in defs:
            if d["key"] not in have:
                DocumentTypeField.objects.create(doc_type=t, **d)
        t.ocr_fields = keys
        t.sort_order = 900 if t.name.lower() == "other" else 100
        t.save(update_fields=["ocr_fields", "sort_order"])
        Document.objects.filter(doc_type=t).update(type_confirmed=True, type_source="migrated")
        DocumentField.objects.filter(document__doc_type=t).exclude(key__in=keys).update(scope="custom")
    for f in DocumentField.objects.filter(scope="custom", label=""):
        f.label = STANDARD.get(f.key.removeprefix("custom:"), (f.key.removeprefix("custom:").replace("_", " ").capitalize(),))[0]
        f.save(update_fields=["label"])


